import java.util.*;

class Solution {
    public int josephus(int n, int k) {
        return solveZeroBased(n, k) + 1;
    }

    private int solveZeroBased(int peopleCount, int stepSize) {
        if (peopleCount == 1) {
            return 0;
        }

        return (solveZeroBased(peopleCount - 1, stepSize) + stepSize) % peopleCount;
    }
}
